        let mut active_axes = self.activity.branch_axes(index, BRANCH_COUNT); while let Some(axis) = active_axes.next() { self.db[index][axis] = (first.db[axis] * first_scale + second.db[axis] * second_scale) + third.db[axis] * third_scale; }
