    #[inline(never)]
    pub(crate) fn store_sub_div_same_denominator(&mut self, index: usize, left: usize, right: usize, denominator: usize) {
        self.mark_derivatives_dirty(index);
        let left_value = self.v[left];
        let right_value = self.v[right];
        let denominator_value = self.v[denominator];
        let reciprocal = 1.0 / denominator_value;
        let delta = left_value - right_value;
        let denominator_scale = -delta * reciprocal * reciprocal;
        self.v[index] = delta * reciprocal;
        let mut active_axes = self.activity.node_axes(index, NODE_COUNT); while let Some(axis) = active_axes.next() { self.dn[index][axis] = (self.dn[left][axis] - self.dn[right][axis]) * reciprocal + self.dn[denominator][axis] * denominator_scale; }
        let mut active_axes = self.activity.branch_axes(index, BRANCH_COUNT); while let Some(axis) = active_axes.next() { self.db[index][axis] = (self.db[left][axis] - self.db[right][axis]) * reciprocal + self.db[denominator][axis] * denominator_scale; }
    }


    pub(crate) fn store_mul_div_from_scalar_lhs_ad(&mut self, index: usize, scalar: f64, denominator: AdValue<NODE_COUNT, BRANCH_COUNT>, right: AdValue<NODE_COUNT, BRANCH_COUNT>) {
        self.mark_derivatives_dirty(index);
        let reciprocal = 1.0 / denominator.value;
        let quotient = scalar * reciprocal;
        let denominator_derivative_scale = -quotient * reciprocal;
        self.v[index] = quotient * right.value;
        let mut active_axes = self.activity.node_axes(index, NODE_COUNT); while let Some(axis) = active_axes.next() { self.dn[index][axis] = denominator.dn[axis] * denominator_derivative_scale * right.value + quotient * right.dn[axis]; }
        let mut active_axes = self.activity.branch_axes(index, BRANCH_COUNT); while let Some(axis) = active_axes.next() { self.db[index][axis] = denominator.db[axis] * denominator_derivative_scale * right.value + quotient * right.db[axis]; }
    }

